const days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const today = new Date();
const dayIndex = today.getDay();

// Mon(1), Wed(3), Sat(6) = property days. All others = experience days.
const propertyDays = [1, 3, 6];
const postType = propertyDays.includes(dayIndex) ? 'property' : 'experience';

const audienceMap = {
  0: { audience: 'Sayulita Community', postStyle: 'Experiential, no hard sell, community tone', ctaStyle: 'None — pure experience', hookExample: 'This is what Sayulita looks like from above the jungle.' },
  1: { audience: 'Sayulita Rentals (actively searching)', postStyle: 'Direct with booking CTA', ctaStyle: 'Book at skyhousesayulita.com', hookExample: 'Three minutes from the break. Panoramic views. Sleeps 8.' },
  2: { audience: 'Riviera Nayarit & Puerto Vallarta Travelers', postStyle: 'Aspirational with soft CTA', ctaStyle: 'Link in comments for availability', hookExample: 'The best address on the Riviera Nayarit is not in a hotel.' },
  3: { audience: 'Digital Nomads & Remote Workers', postStyle: 'Identity-specific, remote work angle', ctaStyle: 'DM for availability', hookExample: 'Your next office has an ocean view and the fastest WiFi in Sayulita.' },
  4: { audience: 'Luxury Travel & Villas', postStyle: 'Brand storytelling, no hard sell', ctaStyle: 'Explore at skyhousesayulita.com', hookExample: 'Above Sayulita. Above the ordinary. SkyHouse.' },
  5: { audience: 'Mexico Expats & Frequent Travelers', postStyle: 'Destination lifestyle with soft CTA', ctaStyle: 'Link in comments', hookExample: 'The Northside of Sayulita keeps its best address quiet for a reason.' },
  6: { audience: 'Surfers & Adventure Travelers', postStyle: 'Identity-specific, surf culture', ctaStyle: 'DM for availability', hookExample: 'Three minutes from the break. Panoramic views of the Pacific. Sleeps 8.' }
};

const config = audienceMap[dayIndex];

return [{
  json: {
    dayIndex,
    dayName: days[dayIndex],
    runDate: today.toISOString().split('T')[0],
    postType,
    audience: config.audience,
    postStyle: config.postStyle,
    ctaStyle: config.ctaStyle,
    hookExample: config.hookExample
  }
}];

const dayConfig = $('Get Day Config').first().json;
const postType = dayConfig.postType;
const skyHouseItems = $('List SkyHouse Photos').all().map(i => i.json);

function parseBunnyFiles(items, cdnHostname, subfolder) {
  return items
    .filter(f => f && !f.IsDirectory && (f.Length > 0 || f.ContentLength > 0))
    .map(f => ({
      objectName: f.ObjectName,
      cdnUrl: subfolder
        ? `https://${cdnHostname}/${subfolder}/${f.ObjectName}`
        : `https://${cdnHostname}/${f.ObjectName}`,
      size: f.Length || f.ContentLength || 0
    }));
}

const skyHouseFiles = parseBunnyFiles(skyHouseItems, 'SkyhouseSayulita.b-cdn.net', null);

if (skyHouseFiles.length === 0) {
  throw new Error('No files in SkyHouse storage. Sample: ' + JSON.stringify(skyHouseItems[0]));
}

const shuffleSkyHouse = [...skyHouseFiles].sort(() => Math.random() - 0.5);
let selected;

if (postType === 'property') {
  selected = [
    { ...shuffleSkyHouse[0], source: 'skyhouse' },
    { ...(shuffleSkyHouse[1] || shuffleSkyHouse[0]), source: 'skyhouse' },
    { ...(shuffleSkyHouse[2] || shuffleSkyHouse[0]), source: 'skyhouse' }
  ];
} else {
  const folder = $('Pick Sayulita Folder').first().json.sayulitaFolder;
  const sayulitaItems = $('List Sayulita Shared Photos').all().map(i => i.json);
  const sayulitaFiles = parseBunnyFiles(sayulitaItems, 'sayulitaandbeyond.b-cdn.net', folder);

  if (sayulitaFiles.length === 0) {
    throw new Error('No files in Sayulita/' + folder + '. Sample: ' + JSON.stringify(sayulitaItems[0]));
  }

  const shuffleSayulita = [...sayulitaFiles].sort(() => Math.random() - 0.5);
  selected = [
    { ...shuffleSkyHouse[0], source: 'skyhouse' },
    { ...shuffleSayulita[0], source: folder },
    { ...(shuffleSayulita[1] || shuffleSayulita[0]), source: folder }
  ];
}

const folderUsed = postType === 'experience' ? $('Pick Sayulita Folder').first().json.sayulitaFolder : null;

return selected.map((photo, idx) => ({
  json: {
    photoIndex: idx,
    objectName: photo.objectName,
    cdnUrl: photo.cdnUrl,
    source: photo.source,
    postType: dayConfig.postType,
    dayIndex: dayConfig.dayIndex,
    dayName: dayConfig.dayName,
    runDate: dayConfig.runDate,
    audience: dayConfig.audience,
    postStyle: dayConfig.postStyle,
    ctaStyle: dayConfig.ctaStyle,
    hookExample: dayConfig.hookExample,
    sayulitaFolder: folderUsed
  }
}));

const uploads = $input.all();
const originalPhotos = $('Pick 3 Photos').all();
const dayConfig = $('Get Day Config').first().json;

if (uploads.length === 0) {
  throw new Error('No photos were uploaded to Facebook. Check the Page Access Token and permissions.');
}

const fbPhotoIds = uploads.map(item => item.json.id || item.json.photo_id);
const cdnUrls = originalPhotos.map(item => item.json.cdnUrl);
const photoNames = originalPhotos.map(item => item.json.objectName);

return [{
  json: {
    fbPhotoIds,
    cdnUrls,
    photoNames,
    photoCount: fbPhotoIds.length,
    dayIndex: dayConfig.dayIndex,
    dayName: dayConfig.dayName,
    runDate: dayConfig.runDate,
    audience: dayConfig.audience,
    postStyle: dayConfig.postStyle,
    ctaStyle: dayConfig.ctaStyle,
    hookExample: dayConfig.hookExample
  }
}];

const item = $input.first();
const postType = item.json.postType;
const folder = item.json.sayulitaFolder;

const systemPrompt = `You are the content creator for SkyHouse Sayulita, a luxury two-level corner penthouse vacation rental in Monterosa, Northside Sayulita, Nayarit, Mexico. Managed by LUX Property Management.

PROPERTY FACTS — use only these, never invent:
- 3 bedrooms, 3 en-suite bathrooms, sleeps up to 8 guests
- Two-level corner penthouse — top floor of Monterosa complex
- Main level: living and dining, full chef kitchen, 2 guest bedrooms, expansive sunset terrace
- Upper level: master suite, BBQ, outdoor dining, rooftop terrace with panoramic ocean views
- Shared infinity pool (Monterosa complex — quiet, panoramic ocean views)
- Private tennis court (Monterosa complex exclusive)
- Starlink WiFi — fastest in Sayulita, suitable for video calls and remote work
- Whole-house purified water system — safe to drink from any tap
- 3-minute walk to beach via Avenida Palmar
- 5-minute walk to town plaza via Calle Juan Escutia
- Quiet Northside location — away from late-night noise
- Secure free garage parking on premises
- Premium linens and toiletries provided
- PVR airport 45 minutes north (Puerto Vallarta International)
- Host: Eño — born and raised in Sayulita, local realtor and surfer
- Eño offers: golf cart and SxS rentals, airport transfers, boat charters, fishing, snorkeling, surf lessons, ATV explorations, jungle hikes, yoga sessions
- Main surf break: 3-minute walk. Playa de los Muertos: quieter local break.
- Monkey Mountain: jungle hike with 360-degree coastal views
- Carricitos Beach: secluded sunset spot, golf cart or ATV required
- Dining: street tacos, organic cafes, upscale seaside dining — all walkable
- Website: skyhousesayulita.com | WhatsApp: +52 322 239 4077

BRAND VOICE:
- Elegant, experiential, warm, confident. Relaxed luxury without pretension.
- Second person or third person only. Never first person.
- Focus on moments and feelings, not feature lists.
- No slang. No generic phrases like perfect vacation rental or great amenities.

POST STRUCTURE:
1. Hook (Line 1): Bold, scroll-stopping opener calling out the specific audience
2. Bridge (Line 2): One sentence connecting the audience to SkyHouse or the featured experience
3. Body (2-3 short paragraphs): Experiential, sensory moments
4. Invitation: Clean call to action as specified
5. Hashtags: At the very end only

ABSOLUTE RULES:
- No markdown: no asterisks, no bold, no headers, no bullet points
- Never mention nightly rates
- Never claim private beach (3-minute walk)
- Never claim private pool (shared with Monterosa complex)
- Never claim on-site chef (self-catering kitchen only)
- Hashtags only at the very end
- 100-200 words total excluding hashtags
- Plain text only`;

let userPrompt;

if (postType === 'property') {
  userPrompt = `Generate a SkyHouse Sayulita Facebook post focused on the PROPERTY.

Audience: ${item.json.audience}
Post style: ${item.json.postStyle}
CTA: ${item.json.ctaStyle}
Hook reference (adapt freely): ${item.json.hookExample}

Focus on the villa, the views, the terraces, the feeling of being at SkyHouse. Make the reader want to book.
Plain text only. No markdown. 100-200 words. Hashtags at end only. Output the post and nothing else.`;
} else {
  userPrompt = `Generate a SkyHouse Sayulita Facebook post focused on the experience: ${folder}.

Audience: ${item.json.audience}
Post style: ${item.json.postStyle}
CTA: ${item.json.ctaStyle}
Hook reference (adapt freely): ${item.json.hookExample}

The post is ENTIRELY about the ${folder} experience in Sayulita. Mention SkyHouse only briefly as the perfect home base — it is NOT the main subject. Make the reader fall in love with the experience first.
Plain text only. No markdown. 100-200 words. Hashtags at end only. Output the post and nothing else.`;
}

return [{
  json: {
    ...item.json,
    claudeRequestBody: JSON.stringify({
      model: 'claude-opus-4-6',
      max_tokens: 1024,
      system: systemPrompt,
      messages: [{ role: 'user', content: userPrompt }]
    })
  }
}];

const item = $input.first();
const claudeResponse = item.json;
const prevData = $('Collect Upload Results').first().json;

let postText = '';
if (claudeResponse.content && Array.isArray(claudeResponse.content) && claudeResponse.content.length > 0) {
  postText = claudeResponse.content[0].text || '';
}

if (!postText.trim()) {
  throw new Error('Claude returned empty post text. Check API key and request format.');
}

const wordCount = postText.trim().split(/\s+/).length;
const warnings = [];

if (wordCount < 80) warnings.push(`Post may be too short: ${wordCount} words`);
if (wordCount > 260) warnings.push(`Post may be too long: ${wordCount} words`);
if (/\*\*|\*[^*]|\bhashtag\b/i.test(postText)) warnings.push('Possible markdown detected');

return [{
  json: {
    postText: postText.trim(),
    wordCount,
    warnings: warnings.join(' | ') || 'None',
    fbPhotoIds: prevData.fbPhotoIds,
    cdnUrls: prevData.cdnUrls,
    photoNames: prevData.photoNames,
    dayName: prevData.dayName,
    audience: prevData.audience,
    runDate: prevData.runDate
  }
}];

const item = $input.first();

const fbPostBody = {
  message: item.json.postText,
  attached_media: item.json.fbPhotoIds.map(id => ({ media_fbid: id }))
};

return [{
  json: {
    ...item.json,
    fbPostBodyJson: JSON.stringify(fbPostBody)
  }
}];

const errorData = $input.first().json;
console.error('SkyHouse workflow error:', JSON.stringify({
  date: new Date().toISOString(),
  workflow: 'SkyHouse Sayulita — Daily Social Post',
  error: errorData.error && errorData.error.message,
  node: errorData.error && errorData.error.node && errorData.error.node.name,
  executionId: errorData.execution && errorData.execution.id
}));
return $input.all();

const dayConfig = $input.first().json;

const allFolders = [
  'Surf', 'Yoga', 'Restaurants', 'Marieta Islands',
  'Monkey Mountain', 'Golf', 'Fishing Charter',
  'Whale Tours', 'SUP', 'Ally Cat', 'CachaSol', 'Local Cultural'
];

const staticData = $getWorkflowStaticData('global');
let usedFolders = staticData.usedFolders || [];

if (usedFolders.length >= allFolders.length) {
  usedFolders = [];
}

const available = allFolders.filter(f => !usedFolders.includes(f));
const folder = available[Math.floor(Math.random() * available.length)];

usedFolders.push(folder);
staticData.usedFolders = usedFolders;

return [{
  json: {
    ...dayConfig,
    sayulitaFolder: folder
  }
}];
